-- 约定：本表由 load_to_mysql.py --init 一次性建表（init 只跑一次）；用 CREATE ... IF NOT EXISTS，勿加回 DROP TABLE（会清空真实库数据）。
CREATE TABLE IF NOT EXISTS tech_financials
(
    company_code                                         CHAR(10)       NOT NULL,
    fiscal_year                                          SMALLINT       NOT NULL COMMENT '报告期(年度)',
    cost_of_revenue                                      DECIMAL(28, 4) NULL COMMENT '营业成本(销售成本)(元)',
    operating_income                                     DECIMAL(28, 4) NULL COMMENT '经营利润(亏损)(US GAAP,非CAS营业利润)(元)',
    research_and_development_expenses                    DECIMAL(28, 4) NULL COMMENT '研发费用(元)',
    selling_general_and_administrative_expenses          DECIMAL(28, 4) NULL COMMENT '销售及管理费用(销售、一般及行政费用)(元)',
    capital_expenditure                                  DECIMAL(28, 4) NULL COMMENT '资本开支(元)',
    payments_for_repurchase_of_ordinary_shares           DECIMAL(28, 4) NULL COMMENT '回购普通股支付的现金(筹资活动流出,正数)(元)',
    share_based_compensation                             DECIMAL(28, 4) NULL COMMENT '股权激励费用(以股份为基础的薪酬,非现金)(元)',
    income_tax_expense                                   DECIMAL(28, 4) NULL COMMENT '所得税费用(负数为所得税收益)(元)',
    interest_income                                      DECIMAL(28, 4) NULL COMMENT '利息收入(元)',
    share_of_earnings_from_equity_method_investments     DECIMAL(28, 4) NULL COMMENT '应占权益法投资收益(亏损)(元)',
    asset_impairment_charges                             DECIMAL(28, 4) NULL COMMENT '资产减值(2011–2024为长期投资及其他资产减值,2025为长期资产减值,口径断档)(元)',
    total_current_liabilities                            DECIMAL(28, 4) NULL COMMENT '流动负债合计(元)',
    equity_attr_non_controlling_interests                DECIMAL(28, 4) NULL COMMENT '非控股股东权益(权益内部分,不含可赎回非控股权益)(元)',
    cash_and_cash_equivalents                            DECIMAL(28, 4) NULL COMMENT '现金及现金等价物(元)',
    short_term_investments                               DECIMAL(28, 4) NULL COMMENT '短期投资净额(元)',
    goodwill                                             DECIMAL(28, 4) NULL COMMENT '商誉(元)',
    property_plant_equipment_net                         DECIMAL(28, 4) NULL COMMENT '固定资产净额(元)',
    operating_lease_right_of_use_assets                  DECIMAL(28, 4) NULL COMMENT '经营租赁使用权资产(元)',
    notes_payable_including_current_portion              DECIMAL(28, 4) NULL COMMENT '应付票据账面总额(含一年内到期；不含借款、可转债,2025不含可交换债)(元)',
    convertible_senior_notes_current_portion_fair_value  DECIMAL(28, 4) NULL COMMENT '可转换优先票据短期部分(公允价值披露口径)(元)',
    convertible_senior_notes_non_current                 DECIMAL(28, 4) NULL COMMENT '可转换优先票据(非流动部分)(元)',
    notes_payable_non_current                            DECIMAL(28, 4) NULL COMMENT '应付票据(非流动部分)(元)',
    gross_margin                                         DECIMAL(12, 4) NULL COMMENT '毛利率%',
    operating_margin                                     DECIMAL(12, 4) NULL COMMENT '经营利润率%(US GAAP经营利润/营业收入)',
    net_margin_attr_parent                    DECIMAL(12, 4) NULL COMMENT '归母净利率%(归母净利润/营业收入)',
    research_and_development_expense_ratio               DECIMAL(12, 4) NULL COMMENT '研发费用率%(研发费用/营业收入)',
    return_on_average_equity                             DECIMAL(12, 4) NULL COMMENT '平均净资产收益率%(归母净利润/期初期末平均归母权益)',
    net_cash_position                                    DECIMAL(28, 4) NULL COMMENT '净现金(现金及现金等价物+短期投资−应付票据,自算)(元)',
    goodwill_impairment_loss                             DECIMAL(28, 4) NULL COMMENT '商誉减值损失(元)',
    advertising_revenue                                  DECIMAL(28, 4) NULL COMMENT '在线营销服务收入(广告收入,仅2007–2017,ASC605口径)(元)',
    other_revenue                                        DECIMAL(28, 4) NULL COMMENT '其他收入(元)',
    source                                               TEXT           NULL COMMENT '数据来源',
    PRIMARY KEY (company_code, fiscal_year),
    CONSTRAINT fk_tech_financials_company FOREIGN KEY (company_code) REFERENCES company (company_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT ='科技互联网业专属年度指标（tech_*_annual.json 里 financials 公共列以外的字段）：与 financials 同主键按需 JOIN，公共列不在此重复；JSON 源字段名与倍数见 data/extract/industry_columns.py，金额统一为元；百度（hk.09888）取自 SEC 20-F（US GAAP），原文人民币百万元，入库 ×1e6，与中国准则的差异写在列注释里';
